<script lang="ts">
 import Breadcrumbs from '$lib/svelte/components/page/Breadcrumbs.svelte';
 import SpellSectionHeading from '$lib/svelte/components/page/SpellSectionHeading.svelte';
 import EditionSelector from '$lib/svelte/components/page/EditionSelector.svelte';
 import InlineContent from '$lib/svelte/components/page/InlineContent.svelte';
 import Faq from '$lib/svelte/components/page/Faq.svelte';
 import type { SpellDetailViewModel } from '$lib/typescript/pages/spellDetail';
 let { model }: { model: SpellDetailViewModel } = $props();
 let isMobile = $state(false); let expanded = $state(new Set(['description']));
 $effect(() => { if (typeof window === 'undefined') return; const m = window.matchMedia('(max-width: 700px)'); const u = () => (isMobile = m.matches); u(); m.addEventListener('change', u); return () => m.removeEventListener('change', u); });
 function toggle(id: string) { const next = new Set(expanded); if (next.has(id)) next.delete(id); else next.add(id); expanded = next; }
</script>
<article class="wiki-article spell-detail new-spell-page">
 <div class="spell-detail__hero"><Breadcrumbs /><header class="spell-detail__header" class:spell-detail__header--with-art={Boolean(model.artwork)}><p class="spell-detail__eyebrow spell-detail__eyebrow--full">{model.level} - {model.name} - {model.edition} - {model.source}</p><p class="spell-detail__eyebrow spell-detail__eyebrow--mobile">{model.level} · {model.edition}</p><h1>{model.name}</h1><div class="spell-detail__classification" aria-label="Spell classification"><span class="spell-detail__classification-pill">✦ {model.level}</span><span class="spell-detail__classification-pill">◉ {model.school}</span></div>{#if model.artwork}<div class="spell-detail__hero-art" aria-hidden="true"><img src={model.artwork} alt="" /></div>{/if}<div class="spell-detail__chips" aria-label="Spell source and edition"><span class="metadata-pill spell-detail__chip">Source: {model.source}</span>{#if model.editionOptions}<EditionSelector current={model.editionId ?? model.edition ?? ''} options={model.editionOptions} />{:else if model.edition}<span class="metadata-pill spell-detail__chip">Edition: {model.edition}</span>{/if}</div></header></div>
 <div class="spell-detail__overview-flow">{#if model.summary || model.summaryContent}<p class="spell-detail__summary spell-detail__summary--desktop">{#if model.summaryContent}<InlineContent content={model.summaryContent} />{:else}{model.summary}{/if}</p><div class="spell-detail__summary-card"><h2>✦ Spell Overview</h2><p>{#if model.summaryContent}<InlineContent content={model.summaryContent} />{:else}{model.summary}{/if}</p></div>{/if}<div class="spell-detail__metadata-area"><dl class="spell-detail__meta">{#each model.metadata as field}<div class:spell-detail__meta-card--compact={field.layout === 'compact'} class:spell-detail__meta-card--wide={field.layout === 'wide'} class:spell-detail__meta-card--extra-wide={field.layout === 'full'}><dt>{field.label}</dt><dd>{field.value}</dd></div>{/each}</dl></div></div>
 {#each model.sections as section}<section class="spell-detail__section" aria-labelledby={section.id}>{#if isMobile}<button class="spell-detail__accordion-trigger" type="button" aria-expanded={expanded.has(section.id)} aria-controls={`${section.id}-content`} onclick={() => toggle(section.id)}><SpellSectionHeading id={section.id} title={section.title} icon={section.icon ?? '/icons/white/game/spell.svg'} /><span class="spell-detail__accordion-subtitle">Spell rules and reference.</span><span class="spell-detail__accordion-chevron">⌄</span></button>{:else}<SpellSectionHeading id={section.id} title={section.title} icon={section.icon ?? '/icons/white/game/spell.svg'} />{/if}<div id={`${section.id}-content`} class="spell-detail__accordion-content" hidden={isMobile && !expanded.has(section.id)}>{#if section.content}{#each section.content as paragraph}<p><InlineContent content={paragraph} /></p>{/each}{:else}{#each section.paragraphs ?? [] as paragraph}<p>{paragraph}</p>{/each}{/if}</div></section>{/each}
 {#if model.faq}<Faq items={model.faq} showHeading={false} />{/if}
</article>
